20	import MatrixModel, { MatrixBaseCellOption, MatrixCellStyleOption, MatrixOption } from '../../coord/matrix/MatrixModel';
21	import ComponentView from '../../view/Component';
22	import { MatrixCellLayoutInfo, MatrixDim, MatrixXYLocator } from '../../coord/matrix/MatrixDim';
23	import Model from '../../model/Model';
24	import { NullUndefined } from '../../util/types';
25	import BoundingRect, { RectLike } from 'zrender/src/core/BoundingRect';
26	import * as vectorUtil from 'zrender/src/core/vector';
27	import { RectShape } from 'zrender/src/graphic/shape/Rect';
28	import { ItemStyleProps } from '../../model/mixin/itemStyle';
29	import { LineStyleProps } from '../../model/mixin/lineStyle';
30	import { LineShape } from 'zrender/src/graphic/shape/Line';
31	import { subPixelOptimize } from 'zrender/src/graphic/helper/subPixelOptimize';
32	import { Group, Text, Rect, Line, XY, setTooltipConfig, expandOrShrinkRect } from '../../util/graphic';
33	import { ListIterator } from '../../util/model';
34	import { clone, retrieve2 } from 'zrender/src/core/util';
35	import { invert } from 'zrender/src/core/matrix';
36	import { MatrixBodyCorner, MatrixBodyOrCornerKind } from '../../coord/matrix/MatrixBodyCorner';
37	import { setLabelStyle } from '../../label/labelStyle';
38	
39	const round = Math.round;
40	
41	// When special border style is defined on cell, it
42	// should be over all of the other borders.
43	type Z2CellDefault = {normal: number, special: number};
44	const Z2_BACKGROUND = 0;
45	const Z2_OUTER_BORDER = 99;
46	const Z2_BODY_CORNER_CELL_DEFAULT: Z2CellDefault = {normal: 25, special: 100};
47	const Z2_DIMENSION_CELL_DEFAULT: Z2CellDefault = {normal: 50, special: 125};
48	
49	class MatrixView extends ComponentView {
50	
51	    static type = 'matrix';
52	    type = MatrixView.type;
53	
54	    render(matrixModel: MatrixModel) {
55	
56	        this.group.removeAll();
57	
58	        const group = this.group;
59	        const coordSys = matrixModel.coordinateSystem;
60	        const rect = coordSys.getRect();
61	        const xDimModel = matrixModel.getDimensionModel('x');
62	        const yDimModel = matrixModel.getDimensionModel('y');
63	        const xDim = xDimModel.dim;
64	        const yDim = yDimModel.dim;
65	
66	        // PENDING:
67	        //  reuse the existing text and rect elements for performance?
68	
69	        renderDimensionCells(
70	            group,
71	            matrixModel
72	        );
73	
74	        createBodyAndCorner(
75	            group,
76	            matrixModel,
77	            xDim,
78	            yDim
79	        );
80	
81	        const borderZ2Option = matrixModel.getShallow('borderZ2', true);
82	        const outerBorderZ2 = retrieve2(borderZ2Option, Z2_OUTER_BORDER);
83	        const dividerLineZ2 = outerBorderZ2 - 1;
84	
85	        // Outer border and overall background. Use separate elements because of z-order:
86	        // The overall background should appear below any other elements.
87	        // But in most cases, the outer border and the divider line should be above the normal cell borders -
88	        // especially when cell borders have different colors. But users may highlight some specific cells by
89	        // overstirking their border, in which case it should be above the outer border.
90	        const bgStyle = matrixModel.getModel('backgroundStyle').getItemStyle(
91	            ['borderWidth']
92	        );
93	        bgStyle.lineWidth = 0;
94	        const borderStyle = matrixModel.getModel('backgroundStyle').getItemStyle(
95	            ['color', 'decal', 'shadowColor', 'shadowBlur', 'shadowOffsetX', 'shadowOffsetY']
96	        );
97	        borderStyle.fill = 'none';
98	        const bgRect = createMatrixRect(rect.clone(), bgStyle, Z2_BACKGROUND);
99	        const borderRect = createMatrixRect(rect.clone(), borderStyle, outerBorderZ2);
100	        bgRect.silent = true;
101	        borderRect.silent = true;
102	        group.add(bgRect);
103	        group.add(borderRect);
104	
105	        // Header split line.
106	        const xDimCell0 = xDim.getUnitLayoutInfo(0, 0);
107	        const yDimCell0 = yDim.getUnitLayoutInfo(1, 0);
108	        if (xDimCell0 && yDimCell0) {
109	            if (xDim.shouldShow()) {
110	                group.add(createMatrixLine(
111	                    {
112	                        x1: rect.x,
113	                        y1: yDimCell0.xy,
114	                        x2: rect.x + rect.width,
115	                        y2: yDimCell0.xy,
116	                    },
117	                    xDimModel.getModel('dividerLineStyle').getLineStyle(),
118	                    dividerLineZ2,
119	                ));
120	            }
121	            if (yDim.shouldShow()) {
122	                group.add(createMatrixLine(
123	                    {
124	                        x1: xDimCell0.xy,
125	                        y1: rect.y,
126	                        x2: xDimCell0.xy,
127	                        y2: rect.y + rect.height,
128	                    },
129	                    yDimModel.getModel('dividerLineStyle').getLineStyle(),
130	                    dividerLineZ2,
131	                ));
132	            }
133	        }
134	    }
135	}
136	
137	function renderDimensionCells(group: Group, matrixModel: MatrixModel) {
138	
139	    renderOnDimension(0);
140	    renderOnDimension(1);
141	
142	    function renderOnDimension(dimIdx: 0 | 1) {
143	        const thisDimModel = matrixModel.getDimensionModel(XY[dimIdx]);
144	        const thisDim = thisDimModel.dim;
145	
146	        if (!thisDim.shouldShow()) {
147	            return;
148	        }
149	
150	        const thisDimBgStyleModel = thisDimModel.getModel('itemStyle');
151	        const thisDimLabelModel = thisDimModel.getModel('label');
152	        const tooltipOption = matrixModel.getShallow('tooltip', true);
153	        const xyLocator: MatrixXYLocator[] = [];
154	
155	        for (const it = thisDim.resetCellIterator(); it.next();) {
156	            const dimCell = it.item;
157	            const shape = {} as RectLike;
158	            BoundingRect.copy(shape, dimCell.rect);
159	
160	            vectorUtil.set(xyLocator, dimCell.id.x, dimCell.id.y);
161	
162	            createMatrixCell(
163	                xyLocator,
164	                matrixModel,
165	                group,
166	                dimCell.option,
167	                thisDimBgStyleModel,
168	                thisDimLabelModel,
169	                thisDimModel,
170	                shape,
171	                dimCell.option.value,
172	                Z2_DIMENSION_CELL_DEFAULT,
173	                tooltipOption
174	            );
175	        }
176	    }
177	}
178	
179	function createBodyAndCorner(
180	    group: Group,
181	    matrixModel: MatrixModel,
182	    xDim: MatrixDim,
183	    yDim: MatrixDim
184	): void {
185	
186	    createBodyOrCornerCells('body', matrixModel.getBody(), xDim, yDim);
187	    if (xDim.shouldShow() && yDim.shouldShow()) {
188	        createBodyOrCornerCells('corner', matrixModel.getCorner(), yDim, xDim);
189	    }
190	
191	    function createBodyOrCornerCells<TBodyOrCornerKind extends MatrixBodyOrCornerKind>(
192	        bodyCornerOptionRoot: TBodyOrCornerKind,
193	        bodyOrCorner: MatrixBodyCorner<TBodyOrCornerKind>,
194	        dimForCoordX: MatrixDim, // Can be `matrix.y` (transposed) for corners.
195	        dimForCoordY: MatrixDim, // Can be `matrix.x` (trnasposed) for corners.
196	    ): void {
197	        // Prevent inheriting from ancestor.
198	        const parentCellModel = new Model(matrixModel.getShallow(bodyCornerOptionRoot, true));
199	        const parentItemStyleModel = parentCellModel.getModel('itemStyle');
200	        const parentLabelModel = parentCellModel.getModel('label');
201	
202	        const itx = new ListIterator<MatrixCellLayoutInfo>();
203	        const ity = new ListIterator<MatrixCellLayoutInfo>();
204	        const xyLocator: number[] = [];
205	        const tooltipOption = matrixModel.getShallow('tooltip', true);
206	
207	        for (dimForCoordY.resetLayoutIterator(ity, 1); ity.next();) {
208	            for (dimForCoordX.resetLayoutIterator(itx, 0); itx.next();) {
209	                const xLayout = itx.item;
210	                const yLayout = ity.item;
211	
212	                vectorUtil.set(xyLocator, xLayout.id.x, yLayout.id.y);
213	                const bodyCornerCell = bodyOrCorner.getCell(xyLocator);
214	
215	                // If in span of an other body or corner cell, never render it.
216	                if (bodyCornerCell && bodyCornerCell.inSpanOf && bodyCornerCell.inSpanOf !== bodyCornerCell) {
217	                    continue;
218	                }
219	
220	                const shape = {} as RectLike;
221	                if (bodyCornerCell && bodyCornerCell.span) {
222	                    BoundingRect.copy(shape, bodyCornerCell.spanRect);
223	                }
224	                else {
225	                    xLayout.dim.getLayout(shape, 0, xyLocator[0]);
226	                    yLayout.dim.getLayout(shape, 1, xyLocator[1]);
227	                }
228	
229	                const bodyCornerCellOption = bodyCornerCell ? bodyCornerCell.option : null;
230	
231	                createMatrixCell(
232	                    xyLocator,
233	                    matrixModel,
234	                    group,
235	                    bodyCornerCellOption,
236	                    parentItemStyleModel,
237	                    parentLabelModel,
238	                    parentCellModel,
239	                    shape,
240	                    bodyCornerCellOption ? bodyCornerCellOption.value : null,
241	                    Z2_BODY_CORNER_CELL_DEFAULT,
242	                    tooltipOption
243	                );
244	            }
245	        }
246	    } // End of createBodyOrCornerCells
247	}
248	
249	function createMatrixCell(
250	    xyLocator: MatrixXYLocator[],
251	    matrixModel: MatrixModel,
252	    group: Group,
253	    cellOption: MatrixBaseCellOption | NullUndefined,
254	    parentItemStyleModel: Model<MatrixCellStyleOption['itemStyle']>,
255	    parentLabelModel: Model<MatrixCellStyleOption['label']>,
256	    parentCellModel: Model<MatrixCellStyleOption>,
257	    shape: RectLike,
258	    textValue: unknown,
259	    zrCellDefault: Z2CellDefault,
260	    tooltipOption: MatrixOption['tooltip'],
261	): void {
262	    // Do not use getModel for handy performance optimization.
263	    _tmpCellItemStyleModel.option = cellOption ? cellOption.itemStyle : null;
264	    _tmpCellItemStyleModel.parentModel = parentItemStyleModel;
265	    _tmpCellModel.option = cellOption;
266	    _tmpCellModel.parentModel = parentCellModel;
267	
268	    // Use different z2 becuase special border may be defined in itemStyle.
269	    const z2 = retrieve2(
270	        _tmpCellModel.getShallow('z2'),
271	        (cellOption && cellOption.itemStyle) ? zrCellDefault.special : zrCellDefault.normal
272	    );
273	    const tooltipOptionShow = tooltipOption && tooltipOption.show;
274	
275	    const cellRect = createMatrixRect(shape, _tmpCellItemStyleModel.getItemStyle(), z2);
276	    group.add(cellRect);
277	
278	    const cursorOption = _tmpCellModel.get('cursor');
279	    if (cursorOption != null) {
280	        cellRect.attr('cursor', cursorOption);
281	    }
282	    let cellText: Text | NullUndefined;
283	
284	    if (textValue != null) {
285	        const text = textValue + '';
286	        _tmpCellLabelModel.option = cellOption ? cellOption.label : null;
287	        _tmpCellLabelModel.parentModel = parentLabelModel;
288	
289	        setLabelStyle(
290	            cellRect,
291	            // Currently do not support other states (`emphasis`, `select`, `blur`)
292	            {normal: _tmpCellLabelModel},
293	            {
294	                defaultText: text,
295	                autoOverflowArea: true,
296	                // By default based on boundingRect. But boundingRect contains borderWidth,
297	                // and borderWidth is half outside the cell. Thus specific `layoutRect` explicitly.
298	                layoutRect: clone(cellRect.shape)
299	            },
300	        );
301	        cellText = cellRect.getTextContent();
302	        if (cellText) {
303	            cellText.z2 = z2 + 1;
304	
305	            const style = cellText.style;
306	            if (style && (style.overflow && style.overflow !== 'none' && style.lineOverflow)) {
307	                // `overflow: 'break'/'breakAll'/'truncate'` does not guarantee prevention of overflow
308	                // when space is insufficient. Use a `clipPath` in such case.
309	                const clipShape = {} as RectLike;
310	                BoundingRect.copy(clipShape, shape);
311	                // `lineWidth` is half outside half inside the bounding rect.
312	                expandOrShrinkRect(clipShape, (cellRect.style?.lineWidth || 0) / 2, true, true);
313	                cellRect.updateInnerText();
314	                cellText.getLocalTransform(_tmpInnerTextTrans);
315	                invert(_tmpInnerTextTrans, _tmpInnerTextTrans);
316	                BoundingRect.applyTransform(clipShape, clipShape, _tmpInnerTextTrans);
317	                cellText.setClipPath(new Rect({shape: clipShape}));
318	            }
319	        }
320	
321	        setTooltipConfig({ // At least for text overflow.
322	            el: cellRect,
323	            componentModel: matrixModel,
324	            itemName: text,
325	            itemTooltipOption: tooltipOption,
326	            formatterParamsExtra: {
327	                xyLocator: xyLocator.slice()
328	            }
329	        });
330	    }
331	
332	    // Set silent
333	    if (cellText) {
334	        let labelSilent = _tmpCellLabelModel.get('silent');
335	        // auto, tooltip of text cells need silient: false, but non-text cells
336	        // do not need a special cursor in most cases.
337	        if (labelSilent == null) {
338	            labelSilent = !tooltipOptionShow;
339	        }
340	        cellText.silent = labelSilent;
341	        cellText.ignoreHostSilent = true;
342	    }
343	    let rectSilent = _tmpCellModel.get('silent');
344	    if (rectSilent == null) {
345	        rectSilent = (
346	            // If no background color in cell, set `rect.silent: false` will cause that only
347	            // the border response to mouse hovering, which is probably weird.
348	            !cellRect.style || cellRect.style.fill === 'none' || !cellRect.style.fill
349	        );
350	    }
351	    cellRect.silent = rectSilent;
352	}
353	const _tmpCellModel = new Model<MatrixCellStyleOption>();
354	const _tmpCellItemStyleModel = new Model<MatrixCellStyleOption['itemStyle']>();
355	const _tmpCellLabelModel = new Model<MatrixCellStyleOption['label']>();
356	const _tmpInnerTextTrans: number[] = [];
357	
358	// FIXME: move all of the subpixel process to Matrix.ts resize, otherwise the result of
359	// `dataToLayout` is not consistent with this rendering, and the caller (like heatmap) can
360	// not precisely align with the matrix border.
361	function createMatrixRect(
362	    shape: RectShape, style: ItemStyleProps, z2: number
363	): Rect {
364	    // Currently `subPixelOptimizeRect` can not be used here because it will break rect alignment.
365	    // Optimize line and rect with the same direction.
366	    const lineWidth = style.lineWidth;
367	    if (lineWidth) {
368	        const x2Original = shape.x + shape.width;
369	        const y2Original = shape.y + shape.height;
370	        shape.x = subPixelOptimize(shape.x, lineWidth, true);
371	        shape.y = subPixelOptimize(shape.y, lineWidth, true);
372	        shape.width = subPixelOptimize(x2Original, lineWidth, true) - shape.x;
373	        shape.height = subPixelOptimize(y2Original, lineWidth, true) - shape.y;
374	    }
375	    return new Rect({
376	        shape,
377	        style: style,
378	        z2,
379	    });
380	}
381	
382	function createMatrixLine(shape: Omit<LineShape, 'percent'>, style: LineStyleProps, z2: number): Line {
383	    const lineWidth = style.lineWidth;
384	    if (lineWidth) {
385	        if (round(shape.x1 * 2) === round(shape.x2 * 2)) {
386	            shape.x1 = shape.x2 = subPixelOptimize(shape.x1, lineWidth, true);
387	        }
388	        if (round(shape.y1 * 2) === round(shape.y2 * 2)) {
389	            shape.y1 = shape.y2 = subPixelOptimize(shape.y1, lineWidth, true);
390	        }
391	    }
392	    return new Line({
393	        shape,
394	        style,
395	        silent: true,
396	        z2,
397	    });
398	}
399	
400	export default MatrixView;
